function getDistances(arr) {
  const groups = new Map();
  for (let i = 0; i < arr.length; i++) {
    if (!groups.has(arr[i])) {
      groups.set(arr[i], []);
    }
    groups.get(arr[i]).push(i);
  }

  const intervals = new Array(arr.length).fill(0);
  for (const indices of groups.values()) {
    const m = indices.length;
    let total = 0;
    for (const index of indices) {
      total += index;
    }
    let prefix = 0;
    for (let k = 0; k < m; k++) {
      const index = indices[k];
      const leftSum = index * k - prefix;
      const rightSum = (total - prefix - index) - index * (m - k - 1);
      intervals[index] = leftSum + rightSum;
      prefix += index;
    }
  }
  return intervals;
}

