function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const pick = rand();
  const distinct = pick < 0.2 ? 1 : pick < 0.5 ? 1 + Math.floor(rand() * 4) : pick < 0.8 ? 1 + Math.floor(rand() * n) : 100000;
  const arr = [];
  for (let i = 0; i < n; i++) {
    if (distinct === 100000) arr.push(1 + Math.floor(rand() * 100000));
    else arr.push(1 + Math.floor(rand() * distinct));
  }
  return [arr];
}
